const settings = $('Carregar configurações').first().json;
const champions = $('Carregar campeãs PerfectPay').all().map((item) => item.json)
  .filter((row) => row.id && !row.archived_at && String(row.platform || '') === 'perfectpay');
const assets = $('Carregar regras e vídeo').all()\n  .filter((item) => String(item.json.asset_type || '') !== 'brand_rules')\n  .map((item) => ({
  tipo: item.json.asset_type,
  titulo: item.json.title,
  conteudo: item.json.content,
}));
const allExperiments = $('Carregar testes PerfectPay').all().map((item) => item.json)
  .filter((row) => String(row.platform || '') === 'perfectpay');
const openStatuses = new Set(['shadow', 'manual_review', 'ready', 'running']);
const openExperiments = allExperiments.filter((row) => openStatuses.has(String(row.status || '')));
const history = $('Carregar histórico PerfectPay').all().map((item) => item.json)
  .filter((row) => String(row.platform || '') === 'perfectpay');
const pendingDrafts = history.filter((row) =>
  String(row.status || '') === 'qa_passed' &&
  row.approval_required === true &&
  !row.approved_at &&
  !row.archived_at
);

const priority = [
  'ABANDONED:1','WAITING_PAYMENT:1','ABANDONED:2','ABANDONED:3',
  'WAITING_PAYMENT:2','WAITING_PAYMENT:3','CANCELED:1','CANCELED:2',
  'CANCELED:3','EXPIRED:1','EXPIRED:2','EXPIRED:3',
  'DELAYED:1','DELAYED:2','DELAYED:3',
];
const rank = new Map(priority.map((key, index) => [key, index]));
const ordered = [...champions].sort((a, b) => {
  const aKey = String(a.recovery_flow || '') + ':' + Number(a.step || 0);
  const bKey = String(b.recovery_flow || '') + ':' + Number(b.step || 0);
  return (rank.get(aKey) ?? 999) - (rank.get(bKey) ?? 999);
});
const baseReference = ordered.find((candidate) => {
  const sameSlot = (row) =>
    String(row.recovery_flow || '') === String(candidate.recovery_flow || '') &&
    Number(row.step || 0) === Number(candidate.step || 0);
  return !openExperiments.some(sameSlot) && !pendingDrafts.some(sameSlot);
});
if (!baseReference?.id) return [];

const latestFinished = allExperiments
  .filter((experiment) =>
    String(experiment.recovery_flow || '') === String(baseReference.recovery_flow || '') &&
    Number(experiment.step || 0) === Number(baseReference.step || 0) &&
    ['paused', 'completed', 'cancelled'].includes(String(experiment.status || ''))
  )
  .sort((a, b) => new Date(b.ended_at || b.updated_at || b.created_at).getTime() - new Date(a.ended_at || a.updated_at || a.created_at).getTime())[0];

const latestReason = String(latestFinished?.decision_reason || '');
const preferredReferenceId = latestReason.startsWith('[TRIAGEM] Versão B promissora:')
  ? latestFinished?.challenger_variant_id
  : latestReason.startsWith('[TRIAGEM] Versão A promissora:')
    ? latestFinished?.champion_variant_id
    : latestReason.startsWith('[TRIAGEM]')
      ? latestFinished?.challenger_variant_id
      : baseReference.id;
const reference = history.find((row) => String(row.id) === String(preferredReferenceId || '')) || baseReference;

const slotHistory = history.filter((row) =>
  String(row.recovery_flow || '') === String(reference.recovery_flow || '') &&
  Number(row.step || 0) === Number(reference.step || 0)
);
const nextVersion = Math.max(0, ...slotHistory.map((row) => Number(row.version_number || 0))) + 1;
const flowLabels = {
  ABANDONED: 'carrinho abandonado',
  WAITING_PAYMENT: 'aguardando pagamento',
  CANCELED: 'compra cancelada',
  DELAYED: 'pagamento atrasado',
  EXPIRED: 'pagamento expirado',
};
const flow = String(reference.recovery_flow || '');
const step = Number(reference.step || 0);
const displayedPrice = Number(reference.displayed_price || 0);
const priceText = displayedPrice > 0
  ? displayedPrice.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  : '';
const offerRule = displayedPrice > 0
  ? 'A condição comercial é exatamente R$ ' + priceText + ' e o código de oferta deve permanecer o mesmo da referência.'
  : 'Este e-mail não possui desconto nem preço promocional. Não invente preço, cupom ou condição comercial.';

const prompt = [
  'Crie UMA nova copy de e-mail para teste na PerfectPay.',
  'Jornada: ' + (flowLabels[flow] || flow) + '.',
  'Etapa: E-mail ' + step + ' de 3.',
  'Você tem liberdade total de estilo, tom, intensidade emocional, estrutura e comprimento. Não existe limite editorial de tamanho ou formato dentro dos campos solicitados.',
  'Procure uma abordagem realmente diferente da referência e com potencial de gerar clique. Você pode ser emocional, dramático, provocativo, narrativo, direto ou usar outro caminho que considerar mais forte.',
  'O usuário fará a revisão humana antes de qualquer teste. Esta copy nunca será publicada automaticamente.',
  'Preserve apenas a integridade técnica: use [nome], não invente fatos, depoimentos, preços, garantias ou condições da oferta e não inclua links ou dados pessoais.',
  offerRule,
  'Devolva somente a estrutura solicitada com: subject, preheader, body, button_text, footer, hypothesis e qa_summary.',
  '',
  'COPY DE REFERÊNCIA (não copie; use apenas para entender o contexto):',
  JSON.stringify({
    subject: reference.subject,
    preheader: reference.preheader,
    body: reference.body,
    button_text: reference.button_text,
    footer: reference.footer,
  }),
  '',
  'VSL, REGRAS DA OFERTA, COPYS ANTIGAS E APRENDIZADOS:',
  JSON.stringify(assets),
].join('\n');

return [{ json: {
  settings_mode: settings.mode,
  platform: 'perfectpay',
  champion_id: reference.id,
  recovery_flow: flow,
  step,
  version_number: nextVersion,
  offer_code: reference.offer_code,
  original_price: reference.original_price == null ? null : Number(reference.original_price),
  displayed_price: reference.displayed_price == null ? null : displayedPrice,
  prompt,
} }];

const draft = $input.first().json.output || {};
const context = $('Preparar contexto sem dados pessoais').first().json;
const history = $('Carregar histórico PerfectPay').all().map((item) => item.json);
const reference = history.find((row) => String(row.id) === String(context.champion_id)) || {};
const errors = [];

for (const field of ['subject', 'preheader', 'body', 'button_text', 'hypothesis']) {
  if (!String(draft[field] || '').trim()) errors.push('Campo vazio: ' + field);
}
if (!String(draft.subject || '').includes('[nome]')) errors.push('Assunto sem [nome]');
if (!String(draft.body || '').includes('[nome]')) errors.push('Corpo sem [nome]');

const joined = [draft.subject, draft.preheader, draft.body, draft.button_text, draft.footer]
  .map((value) => String(value || '')).join(' ');
if (/https?:\/\//i.test(joined)) errors.push('Copy contém link; o Motor é responsável pelo checkout');
if (/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(joined)) errors.push('Copy contém endereço de e-mail');

const expectedPrice = Number(context.displayed_price || 0);
const commaPrice = expectedPrice.toFixed(2).replace('.', ',');
if (expectedPrice > 0 && !joined.includes(commaPrice) && !joined.includes(expectedPrice.toFixed(2))) {
  errors.push('Preço obrigatório R$ ' + commaPrice + ' ausente');
}
if (expectedPrice === 0 && /r\$\s*\d/i.test(joined)) {
  errors.push('Copy sem desconto introduziu preço não autorizado');
}
if (String(draft.subject || '').trim() === String(reference.subject || '').trim()) {
  errors.push('Assunto idêntico ao da referência');
}

return [{ json: {
  platform: 'perfectpay',
  recovery_flow: context.recovery_flow,
  step: context.step,
  version_number: context.version_number,
  role: errors.length ? 'rejected' : 'challenger',
  status: errors.length ? 'rejected' : 'qa_passed',
  subject: String(draft.subject || '').trim(),
  preheader: String(draft.preheader || '').trim(),
  body: String(draft.body || '').trim(),
  button_text: String(draft.button_text || '').trim(),
  footer: String(draft.footer || '').trim(),
  offer_code: context.offer_code,
  original_price: context.original_price,
  displayed_price: context.displayed_price,
  hypothesis: String(draft.hypothesis || '').trim(),
  generated_by: 'openai_gpt_5_mini',
  parent_variant_id: context.champion_id,
  qa_passed: errors.length === 0,
  qa_report: {
    errors,
    summary: String(draft.qa_summary || ''),
    generated_at: new Date().toISOString(),
    pii_used: false,
    content_freedom: true,
    review_required: true,
    platform: 'perfectpay',
    recovery_flow: context.recovery_flow,
    step: context.step,
  },
  approval_required: true,
} }];
